def perimeter(shape):
    if shape[0] == "square":
        return shape[1] * shape[1]
    return 2 * (shape[1] + shape[2])

solution:
def rect_perimeter(w, h):
    return 2 * (w + h)


def perimeter(shape):
    if shape[0] == "square":
        return rect_perimeter(shape[1], shape[1])
    return rect_perimeter(shape[1], shape[2])

